// 1. Settings - Adjusted for Lahore Time (PKT)
const businessHoursStart = "08:00:00+05:00"; 
const businessHoursEnd = "17:30:00+05:00";   

// 2. Grab all incoming items
const inputData = $input.all().map(item => item.json); 

function getDateWithTime(dateString, time) {
  const datePart = new Date(dateString).toISOString().split("T")[0];
  return new Date(`${datePart}T${time.replace('+05:00', '')}+05:00`);
}

function getDayOfWeek(dateString) {
  const daysOfWeek = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  return daysOfWeek[new Date(dateString).getDay()];
}

function addDays(date, days) {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

function formatDate(date) {
  return date.toISOString().split('T')[0];
}

// 3. UPDATED LOGIC: Set the window to exactly 2 weeks starting TODAY
const today = new Date();
// Normalize to midnight UTC to avoid partial day issues
const minDate = new Date(today.toISOString().split('T')[0]); 
const maxDate = addDays(minDate, 13); // Today + 13 more days = 14 days total

const eventsByDate = {};
inputData.forEach(event => {
  if (event.start && (event.start.dateTime || event.start.date)) {
    // Handle both timed events and all-day events for sorting
    const dateKey = new Date(event.start.dateTime || event.start.date).toISOString().split("T")[0];

    if (!eventsByDate[dateKey]) eventsByDate[dateKey] = [];

    if (event.transparency !== "transparent" && event.start.dateTime) {
      eventsByDate[dateKey].push({
        start: new Date(event.start.dateTime),
        end: new Date(event.end.dateTime)
      });
    }
  }
});

const freeTimeSlots = [];

// Loop through exactly 14 days
for (let currentDate = new Date(minDate); currentDate <= maxDate; currentDate = addDays(currentDate, 1)) {
    const dateStr = formatDate(currentDate);
    const busyEvents = eventsByDate[dateStr] || [];
    const businessStart = getDateWithTime(dateStr, businessHoursStart);
    const businessEnd = getDateWithTime(dateStr, businessHoursEnd);

    // If no busy events, the whole business day is free
    if (busyEvents.length === 0) {
      freeTimeSlots.push({
        date: dateStr,
        dayOfWeek: getDayOfWeek(dateStr),
        freeStart: businessStart.toISOString(),
        freeEnd: businessEnd.toISOString()
      });
      continue;
    }

    busyEvents.sort((a, b) => a.start - b.start);

    // Check gap before first event
    if (busyEvents[0].start > businessStart) {
      freeTimeSlots.push({
        date: dateStr,
        dayOfWeek: getDayOfWeek(dateStr),
        freeStart: businessStart.toISOString(),
        freeEnd: busyEvents[0].start.toISOString()
      });
    }

    // Check gaps between events
    for (let i = 0; i < busyEvents.length - 1; i++) {
      if (busyEvents[i].end < busyEvents[i+1].start) {
        freeTimeSlots.push({
          date: dateStr,
          dayOfWeek: getDayOfWeek(dateStr),
          freeStart: busyEvents[i].end.toISOString(),
          freeEnd: busyEvents[i+1].start.toISOString()
        });
      }
    }

    // Check gap after last event
    if (busyEvents[busyEvents.length - 1].end < businessEnd) {
      freeTimeSlots.push({
        date: dateStr,
        dayOfWeek: getDayOfWeek(dateStr),
        freeStart: busyEvents[busyEvents.length - 1].end.toISOString(),
        freeEnd: businessEnd.toISOString()
      });
    }
}

return [{ json: { freeTimeSlots } }];
